namespace docking.widgets.trable;






/**
 * Base class for GTrable cell renderers.
 *
 * @param <T> the data model row object type
 */
public class DefaultGTrableCellRenderer<T> : DefaultTableCellRenderer, GTrableCellRenderer<T> {

	/* @Override */
	public Component getCellRenderer(GTrable<object> trable, T value, bool isSelected,
			bool hasFocus, int row, int column) {

		if (trable == null) {
			return this;
		}

		Color fg = isSelected ? trable.getSelectionForeground() : trable.getForeground();
		Color bg = isSelected ? trable.getSelectionBackground() : trable.getBackground();
		base.setForeground(fg);
		base.setBackground(bg);

		setFont(trable.getFont());
		setValue(value);

		return this;

	}

}
